                G += grad[base + j]
                if not math.isfinite(G):
                    raise ValueError(
                        "log_softmax_batch backward intermediate"
                        " must be finite"
                    )
            for j in range(cols):
                k = base + j
                e = math.exp(saved_l[k])
                if not math.isfinite(e):
                    raise ValueError(
                        "log_softmax_batch backward intermediate"
                        " must be finite"
                    )
                product = e * G
